/// <summary>
/// Creates a <c>METSalesOrderWaveIdExtractEventContract</c>
/// </summary>
/// <param name = "_waveId">WaveId</param>
/// <returns>A <c>METSalesOrderWaveIdExtractEventContract</c>.</returns>
public static METSalesOrderWaveGeneratedBusinessEventContract newFromSalesOrderExtractionDetails(METWaveId _waveId, int _salesLineCount)
{
    METSalesOrderWaveGeneratedBusinessEventContract contract = new METSalesOrderWaveGeneratedBusinessEventContract();
    contract.parmWaveId(_waveId);
    contract.parmCountOfLines(_salesLineCount);

    return contract;
}

/// <summary>
/// Get or set wave id
/// </summary>
/// <param name = "_waveId">Wave Id</param>
/// <returns>METWaveId</returns>
[DataMember('WaveId'), BusinessEventsDataMember("@MET:WaveId")]
public METWaveId parmWaveId(METWaveId _waveId = waveId)
{
    waveId = _waveId;

    return waveId;
}

/// <summary>
/// Get or set count of sales lines related to the wave
/// </summary>
/// <param name = "_countOfLines">Count of sales lines</param>
/// <returns>int</returns>
[DataMember('CountOfLines'), BusinessEventsDataMember("@MET:METCountOfLines")]
public int parmCountOfLines(int _countOfLines = countOfLines)
{
    countOfLines = _countOfLines;

    return countOfLines;
}

